/* ════════════════════════════════════════════════════════════
   KMI BROKERS — DocuSign Email Classifier & File Sorter
   ════════════════════════════════════════════════════════════
   CONFIGURATION: Edit CARRIERS array to add/remove carriers.
   All keyword matching is CASE-INSENSITIVE.
   ═══════════════════════════════════════════════════════════ */

// ── EDITABLE CONFIG ──────────────────────────────────────────
const CARRIERS = [
  'Wawanesa', 'Dominion', 'Intact', 'Aviva', 'Economical',
  'Pembridge', 'Gore Mutual', 'SGI', 'Travelers', 'Chubb',
  'Belairdirect', 'TD Insurance', 'RSA', 'Northbridge'
  // ← Add more carriers here
];

// Shared files: ALL three words must appear in the filename
const CONSENT_KEYWORDS = ['personal', 'information', 'consent'];
// Shared files: this word anywhere in the filename
const SUMMARY_KEYWORD  = 'summary';
// Files with any of these → IGNORED (never attached anywhere)
const IGNORE_KEYWORDS  = ['pac', 'mac'];
// ─────────────────────────────────────────────────────────────

const HTML_BODY = `<div style="font-family: Arial, sans-serif; font-size: 12px; color: #333; line-height: 1.6;">
  <p style="margin: 0 0 14px;">Please find the attached signed documents for your review and processing.</p>
  <hr style="border: none; border-top: 1px solid #ccc; margin: 16px 0;">
  <table cellpadding="0" cellspacing="0"><tr><td>
    <span style="font-size: 15px; font-weight: bold; color: #1a3a6e;">Oleh (Finn) Babinskyi</span>&nbsp;<span style="color: #444; font-size: 11px;">RIBO &amp; LLQP</span><br>
    <span style="color: #666; font-style: italic;">Customer Service Representative</span><br><br>
    1430 Hurontario Street, Port Credit<br>
    Mississauga, Ontario&nbsp; L5G 3H4<br><br>
    <span style="color:#555">Buss:</span> (905) 486-0440&nbsp;&nbsp;
    <span style="color:#555">Dir:</span> (905) 486-0437&nbsp;&nbsp;
    <span style="color:#555">Fax:</span> (905) 486-0441<br>
    <span style="color:#555">Email:</span> <a href="mailto:olehb@kmibrokers.com" style="color:#1a3a6e;text-decoration:none;">olehb@kmibrokers.com</a>&nbsp;&nbsp;
    <span style="color:#555">Web:</span> <a href="https://www.kmibrokers.com" style="color:#1a3a6e;text-decoration:none;">www.kmibrokers.com</a><br><br>
    <img src="UPDATE_WITH_YOUR_LOGO_URL" alt="KMI Brokers" style="max-width:200px;height:auto;display:block;"><br>
    <p style="font-size:9px;color:#999;max-width:560px;border-top:1px solid #e0e0e0;padding-top:8px;margin:0;line-height:1.4;">
      <strong>DISCLAIMER:</strong> This email (including any attachments) is intended for the sole use of the intended recipient/s and may contain material that is CONFIDENTIAL AND PRIVATE COMPANY INFORMATION. Any review or reliance by others or copying or distribution or forwarding of any or all of the contents in this message is STRICTLY PROHIBITED. If you are not the intended recipient, please contact the sender by email and delete all copies; your cooperation in this regard is appreciated.
    </p>
  </td></tr></table>
</div>`;

// ═══════════════════════════ PROCESSING ═════════════════════
const item    = $input.first();
const subject = (item.json.subject || '').trim();
const subLow  = subject.toLowerCase();

// 1. BUSINESS TYPE
const businessType = subLow.includes('remarket') ? 'REMARKET' : 'NEW BUSINESS';

// 2. CLIENT ID  (fixed regex: \s* matches optional whitespace after "CC:")
const ccMatch  = subject.match(/CC:\s*([A-Z0-9]+)/i);
const clientId = ccMatch ? ccMatch[1].toUpperCase() : 'UNKNOWN';

// 3. CARRIER
let carrier = 'UNKNOWN';
for (const c of CARRIERS) {
  if (subLow.includes(c.toLowerCase())) { carrier = c.toUpperCase(); break; }
}

// 4. FILE SORTING
const binary  = item.binary || {};
const buckets = { home: [], auto: [], lpv: [], shared: [], ignored: [] };

const isConsentForm = (n) => CONSENT_KEYWORDS.every(kw => n.includes(kw));

for (const [key, binData] of Object.entries(binary)) {
  const fname = (binData.fileName || '').toLowerCase();
  if (IGNORE_KEYWORDS.some(kw => fname.includes(kw)))          { buckets.ignored.push(key); continue; }
  if (fname.includes('lpv'))                                    { buckets.lpv.push(key);     continue; }
  if (isConsentForm(fname) || fname.includes(SUMMARY_KEYWORD)) { buckets.shared.push(key);  continue; }
  const isHome = fname.includes('home');
  const isAuto = fname.includes('auto');
  if (isHome) buckets.home.push(key);
  if (isAuto) buckets.auto.push(key);
  if (!isHome && !isAuto) buckets.shared.push(key); // safe fallback
}

// 5. LPV PRODUCT TYPE
const lpvHasAuto   = buckets.lpv.some(k => (binary[k]?.fileName || '').toLowerCase().includes('auto'));
const lpvHasTenant = buckets.lpv.some(k => (binary[k]?.fileName || '').toLowerCase().includes('tenant'));
let lpvProductType = 'AUTO & TENANTS';
if (lpvHasAuto  && !lpvHasTenant) lpvProductType = 'AUTO';
if (lpvHasTenant && !lpvHasAuto)  lpvProductType = 'TENANTS';

// 6. ROUTE FLAGS
const hasHome = subLow.includes('home') || buckets.home.length > 0;
const hasAuto = subLow.includes('auto') || buckets.auto.length > 0;
const hasLPV  = buckets.lpv.length > 0;

// 7. SUBJECT LINES  (BINDER and POLICIES left blank for manual entry)
const homeSubj = `${businessType} / CC: ${clientId} / HOME / BINDER:  / ${carrier}`;
const autoSubj = `${businessType} / CC: ${clientId} / AUTO / BINDER:  / ${carrier}`;
const lpvSubj  = `LPV / CC: ${clientId} / ${lpvProductType} / POLICIES:  / ${carrier}`;

return [{
  json: {
    hasHome, hasAuto, hasLPV,
    homeSubj, autoSubj, lpvSubj,
    // Comma-joined binary keys for each route — used by the Build Payload nodes
    homeFiles: [...buckets.home, ...buckets.shared].join(','),
    autoFiles: [...buckets.auto, ...buckets.shared].join(','),
    lpvFiles:  buckets.lpv.join(','),
    signatureHtml: HTML_BODY
  },
  binary  // pass ALL binary data downstream — each Build Payload node filters its own
}];

const item          = $input.first();
const allBin        = item.binary || {};
const subject       = item.json['homeSubj'];
const signatureHtml = item.json.signatureHtml;

// Split comma-joined file keys back to array; skip any that don't exist in binary
const rawKeys = (item.json['homeFiles'] || '').split(',');
const keys    = rawKeys.map(k => k.trim()).filter(k => k && allBin[k]);

// Build Graph API attachment objects
// n8n stores binary data as base64 in binData.data — exactly what Graph API needs
const attachments = keys.map(k => ({
  "@odata.type":  "#microsoft.graph.fileAttachment",
  "name":         allBin[k].fileName || k,
  "contentType":  allBin[k].mimeType  || "application/pdf",
  "contentBytes": allBin[k].data
}));

return [{
  json: {
    subject,
    body: { contentType: "HTML", content: signatureHtml },
    toRecipients: [{ emailAddress: { address: "plprocessing@kmibrokers.com" } }],
    attachments
  }
}];

const item          = $input.first();
const allBin        = item.binary || {};
const subject       = item.json['autoSubj'];
const signatureHtml = item.json.signatureHtml;

// Split comma-joined file keys back to array; skip any that don't exist in binary
const rawKeys = (item.json['autoFiles'] || '').split(',');
const keys    = rawKeys.map(k => k.trim()).filter(k => k && allBin[k]);

// Build Graph API attachment objects
// n8n stores binary data as base64 in binData.data — exactly what Graph API needs
const attachments = keys.map(k => ({
  "@odata.type":  "#microsoft.graph.fileAttachment",
  "name":         allBin[k].fileName || k,
  "contentType":  allBin[k].mimeType  || "application/pdf",
  "contentBytes": allBin[k].data
}));

return [{
  json: {
    subject,
    body: { contentType: "HTML", content: signatureHtml },
    toRecipients: [{ emailAddress: { address: "plprocessing@kmibrokers.com" } }],
    attachments
  }
}];

const item          = $input.first();
const allBin        = item.binary || {};
const subject       = item.json['lpvSubj'];
const signatureHtml = item.json.signatureHtml;

// Split comma-joined file keys back to array; skip any that don't exist in binary
const rawKeys = (item.json['lpvFiles'] || '').split(',');
const keys    = rawKeys.map(k => k.trim()).filter(k => k && allBin[k]);

// Build Graph API attachment objects
// n8n stores binary data as base64 in binData.data — exactly what Graph API needs
const attachments = keys.map(k => ({
  "@odata.type":  "#microsoft.graph.fileAttachment",
  "name":         allBin[k].fileName || k,
  "contentType":  allBin[k].mimeType  || "application/pdf",
  "contentBytes": allBin[k].data
}));

return [{
  json: {
    subject,
    body: { contentType: "HTML", content: signatureHtml },
    toRecipients: [{ emailAddress: { address: "plprocessing@kmibrokers.com" } }],
    attachments
  }
}];
